  "anomaly_detected": true,
  "confidence": 0.98,
  "anomalies": [
    {
      "category": "other",
      "components": ["FCC1"],
      "pins": ["FCC1.48", "FCC1.73"],
      "nets": ["UART3_TX_FCC", "UART3_RX_FCC"],
      "observed": "FCC1 pins 48 and 73 are marked VCAP but are assigned to UART3_TX_FCC and UART3_RX_FCC. No VCAP capacitors are shown on those pins.",
      "expected": "The STM32H753 VCAP pins should be used only with the required regulator capacitors, not as UART signals; UART signals should use suitable GPIO/alternate-function pins.",
      "evidence": [
        {
          "source": "schematic",
          "quote": "FCC1 STM32H753VITx: pins 48 and 73 are labeled VCAP; the attached nets are UART3_TX_FCC and UART3_RX_FCC. Sheet Flight Control Computer, page 2."
        }
      ],
      "impact": "The MCU's internal regulator may not operate correctly without the required VCAP capacitors, potentially preventing startup. The UART3 signals are also connected to regulator pins rather than usable UART pins.",
      "confidence": 0.99
    },
    {
      "category": "other",
      "components": ["U6"],
      "pins": ["U6.5", "U6.3"],
      "nets": ["+3.3V", "GND"],
      "observed": "TMP100 ADD0 (pin 5) is tied to +3.3V and ADD1 (pin 3) to GND, while the schematic labels the I2C address as 0x4E. Those strap levels select a different TMP100 address (0x49 using the standard 7-bit address), not 0x4E.",
      "expected": "The address straps and the firmware's expected address should agree; for a TMP100, 0x4E is not consistent with the shown address-pin configuration.",
      "evidence": [
        {
          "source": "schematic",
          "quote": "U6 TMP100: ADD0 pin 5 is connected to +3.3V, ADD1 pin 3 to GND; nearby note: “I2C address: 0x4E”. Sheet NAVC Peripherals, page 6."
        },
        {
          "source": "spec",
          "quote": "“Temperature sensor | TMP100, I2C addr 0x4E” (§2, Component Table)."
        }
      ],
      "impact": "If firmware uses the documented 0x4E address, it will not communicate with the temperature sensor at its strapped address.",
      "confidence": 0.88
    }
  ],
  "summary": "The FCC STM32H753 VCAP pins are assigned to UART nets and lack their required capacitors, a serious power-up and connectivity error. The TMP100 address annotation also conflicts with its address-pin straps."
}

